import{_ as i,o as t,c as a,a3 as s}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Build from Source","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Build from Source | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/dev/build"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/dev/build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/dev/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/dev/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/dev/build"}]]},"headers":[],"relativePath":"clice/dev/build.md","filePath":"en/clice/dev/build.md","lastUpdated":1791267063000}'),l={name:"clice/dev/build.md"};function n(o,e,r,d,c,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="build-from-source" tabindex="-1">Build from Source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from Source&quot;">​</a></h1><p>clice depends on C++23 features and requires a modern C++ toolchain. We also need to link against LLVM/Clang to parse ASTs. Both come from <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a>, clice-io&#39;s clang toolchain: <a href="https://bazel.build" target="_blank" rel="noreferrer">Bazel</a> builds clice with xclang&#39;s toolchain and links the prebuilt LLVM/Clang libraries of the same xclang release, both downloaded by Bazel itself. The two must match: the libraries hold ThinLTO bitcode, which only the toolchain of that release reads.</p><p>To simplify setup and keep builds reproducible, we <strong>strongly recommend</strong> <a href="https://pixi.prefix.dev/latest" target="_blank" rel="noreferrer">pixi</a> to manage the development environment. Dependency versions are pinned in <code>pixi.toml</code>; Bazel&#39;s are in <code>MODULE.bazel</code>.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><p>Install pixi following the <a href="https://pixi.prefix.dev/latest/installation" target="_blank" rel="noreferrer">official guide</a>.</p><p>We ship several tasks; the commands below build and run tests:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># build (default RelWithDebInfo) into build/RelWithDebInfo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># unit + integration + smoke + snap tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>For finer-grained tasks (first argument sets the build type):</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unit-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span></code></pre></div><p><code>pixi run build</code> builds <code>//:dist</code> with Bazel. Each build type has a directory of its own, <code>build/&lt;type&gt;</code>, whose <code>bin</code> is Bazel&#39;s output tree of that type: clice is <code>build/&lt;type&gt;/bin/bin/clice</code>, next to the resource directory it reads clang&#39;s headers from, <code>build/&lt;type&gt;/bin/lib/clang</code>; the tests and the editors run it from there.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Run <code>pixi shell</code> to enter a shell with all env vars configured, and <code>npx bazel</code> there for Bazel itself.</p></div><h2 id="bazel" tabindex="-1">Bazel <a class="header-anchor" href="#bazel" aria-label="Permalink to &quot;Bazel&quot;">​</a></h2><p>Bazel is run through <a href="https://github.com/bazelbuild/bazelisk" target="_blank" rel="noreferrer">bazelisk</a>, an npm package of the repository (<code>npm install</code> installs it), which fetches the Bazel release <code>.bazelversion</code> names:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:bin/clice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:bin/unit_tests</span></span></code></pre></div><p>The build types are configurations of <code>.bazelrc</code>:</p><table tabindex="0"><thead><tr><th>Configuration</th><th>Effect</th></tr></thead><tbody><tr><td><code>--config=RelWithDebInfo</code></td><td>The default: optimized, with debug info</td></tr><tr><td><code>--config=Debug</code></td><td>Unoptimized, with Address Sanitizer; on Windows without it</td></tr></tbody></table><p>Options after <code>--</code> reach Bazel through <code>pixi run build</code>, for example <code>pixi run build RelWithDebInfo -- //:package</code>.</p><p><code>--platforms=@xclang//platforms:&lt;triple&gt;</code> builds for another architecture of the host&#39;s operating system, for example <code>--platforms=@xclang//platforms:aarch64-unknown-linux-gnu</code> on x86_64 Linux.</p><p>The LLVM/Clang libraries hold ThinLTO bitcode, so every link of a program redoes their code generation, minutes per program. lld keeps what it generated in a cache, <code>/var/tmp/xclang-thinlto</code> (<code>C:/xclang-thinlto</code> on Windows), and later links take seconds.</p><p><code>npx bazel build //:package //:symbols</code> builds the release archive and the symbol package, clice&#39;s GSYM for <code>scripts/symbolize.py</code>: <code>clice.tar.gz</code> and <code>clice-symbol.tar.xz</code> in <code>build/&lt;type&gt;/bin</code> (<code>.zip</code> on Windows).</p><p><code>npx bazel run @compdb//:refresh</code> writes a <code>compile_commands.json</code> of clice&#39;s own sources to the repository root, for clice to work on its own code.</p><p>On Windows, Bazel&#39;s default output root is too deep for Windows paths; put a short one in <code>%USERPROFILE%\\.bazelrc</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startup --output_user_root=C:/b</span></span></code></pre></div><p>Bazel also needs a Bash on Windows, which <a href="https://gitforwindows.org" target="_blank" rel="noreferrer">Git for Windows</a> provides.</p><h2 id="about-llvm" tabindex="-1">About LLVM <a class="header-anchor" href="#about-llvm" aria-label="Permalink to &quot;About LLVM&quot;">​</a></h2><p>clice calls Clang APIs to parse C++ code, so it must link against LLVM/Clang, of the exact version it is written for: the system LLVM package cannot be used directly.</p><p>Every <a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">xclang</a> release publishes prebuilt LLVM/Clang libraries (the <code>libclang-*</code> archives) for all six targets, built by that release&#39;s toolchain, and its Bazel module makes them repositories Bazel downloads with the toolchain.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>Debug builds enable Address Sanitizer and link the ASan-instrumented libraries xclang publishes for x86_64 Linux and arm64 macOS; arm64 Linux and x86_64 macOS have none, and no Debug build. Debug builds for Windows link the release libraries, without Address Sanitizer.</p></div><p>A build of LLVM/Clang of one&#39;s own replaces the release&#39;s with <code>--repo_env=XCLANG_LIBCLANG_ROOT=&lt;directory&gt;</code> (<code>XCLANG_LIBCLANG_ASAN_ROOT</code> for the ASan one); it has to be built the way xclang builds it, by xclang&#39;s <code>scripts/toolchain.ts</code>; see <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a>.</p>`,29)])])}const g=i(l,[["render",n]]);export{u as __pageData,g as default};
